import React, { useState } from "react";

export default function AddProductModal({ onClose }) {
    const sizes = ["XS", "S", "M", "L", "XL", "XXL"];
    const colors = [
      "Noir",
      "Rose",
      "Rose Clair",
      "Beige",
      "Blanc",
      "Vert",
      "Bleu",
      "Marron",
      "Rouge",
    ];
  
    const [selectedSizes, setSelectedSizes] = useState([]);
    const [selectedColors, setSelectedColors] = useState([]);
    const [name, setName] = useState("");
    const [price, setPrice] = useState("");
  
    const toggleSize = (size) => {
      setSelectedSizes((prev) =>
        prev.includes(size) ? prev.filter((s) => s !== size) : [...prev, size]
      );
    };
  
    const toggleColor = (color) => {
      setSelectedColors((prev) =>
        prev.includes(color) ? prev.filter((c) => c !== color) : [...prev, color]
      );
    };
  
    const handleAddProduct = () => {
      console.log({ name, price, selectedSizes, selectedColors });
      onClose();
    };
  
    return (
      <div className="modal-backdrop">
        <div className="modal-card">
          <div className="modal-header">
            <span className="modal-back" onClick={onClose}>
              ← Retour
            </span>
            <h2>Ajouter Produit</h2>
          </div>
  
          <div className="modal-body">
            <label>Nom de produit</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Nom du produit"
            />
  
            <label>Tailles disponibles</label>
            <div className="sizes-container">
              {sizes.map((size) => (
                <div
                  key={size}
                  className={`size-circle ${
                    selectedSizes.includes(size) ? "selected" : ""
                  }`}
                  onClick={() => toggleSize(size)}
                >
                  {size}
                </div>
              ))}
            </div>
  
            <label>Couleurs disponibles</label>
            <div className="colors-container">
              {colors.map((color) => (
                <div
                  key={color}
                  className={`color-pill ${
                    selectedColors.includes(color) ? "selected" : ""
                  }`}
                  onClick={() => toggleColor(color)}
                >
                  {color}
                </div>
              ))}
            </div>
  
            <label>Prix</label>
            <input
              type="text"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder="Prix du produit"
            />
  
            <button className="upload-photo-btn">Ajouter photos</button>
          </div>
  
          <button className="add-product-final-btn" onClick={handleAddProduct}>
            Ajouter ce produit
          </button>
        </div>
      </div>
    );
  }
